function WriteTextFileRequest(; session_id, path, content, meta = nothing)
    json = Dict{String,Any}()
    json["sessionId"] = _convert_member_to_json(SessionId, session_id)
    json["path"] = _convert_member_to_json(String, path)
    json["content"] = _convert_member_to_json(String, content)
    _write_optional!(json, "_meta", Union{Nothing,Dict{String,Any}}, meta)
    WriteTextFileRequest(json)
end

function Base.getproperty(object::WriteTextFileRequest, name::Symbol)
