function convert_from_json(::Type{ElicitationContentValue}, value)
    _is_json_kind(value, "string") && return convert_from_json(String, value)
    _is_json_kind(value, "integer") && return convert_from_json(Int, value)
    _is_json_kind(value, "number") && return convert_from_json(Float64, value)
    _is_json_kind(value, "boolean") && return convert_from_json(Bool, value)
    _is_json_kind(value, "array") && return convert_from_json(Vector{String}, value)
    _throw_shape_error(ElicitationContentValue, value)
end

